# examples/build_hello_llama.ps1
#
# Windows PowerShell 5.1 compatible. Builds hello_llama.exe against a forked
# llama.cpp tree with the .dll.a import libraries generated by
# tools/build-windows.ps1. Safe to re-run.
#
# Usage:
#   .\build_hello_llama.ps1 [llama.cpp dir] [build/bin dir]
#   $env:LLAMA_CPP_DIR = 'C:\path\to\llama.cpp'; .\build_hello_llama.ps1
#   $env:LLAMA_BUILD_DIR = 'C:\path\to\bin'; .\build_hello_llama.ps1

param(
    [string]$LlamaCpp = $env:LLAMA_CPP_DIR,
    [string]$BuildDir = $env:LLAMA_BUILD_DIR
)

function Fail {
    param([string]$Message)
    Write-Host $Message -ForegroundColor Red
    exit 1
}

$ProjectDir = Split-Path -Parent $PSScriptRoot
$IncDir = Join-Path $ProjectDir 'inc'
$UsingSubmodule = $false

if (-not $LlamaCpp) {
    $LlamaCpp = Join-Path $ProjectDir 'vendor\llama.cpp'
    $UsingSubmodule = $true
    if (-not (Test-Path (Join-Path $LlamaCpp 'CMakeLists.txt'))) {
        Fail "llama.cpp submodule not populated at $LlamaCpp; run: git submodule update --init"
    }
}
if (-not (Test-Path $LlamaCpp -PathType Container)) {
    Fail "llama.cpp directory not found: $LlamaCpp"
}
$LlamaCpp = (Resolve-Path $LlamaCpp).Path

if (-not $BuildDir) {
    $candidates = @(
        (Join-Path $LlamaCpp 'build-windows\bin\Release'),
        (Join-Path $LlamaCpp 'build-windows\bin'),
        (Join-Path $LlamaCpp 'build-cuda\bin\Release'),
        (Join-Path $LlamaCpp 'build-cuda\bin'),
        (Join-Path $LlamaCpp 'build-vulkan\bin\Release'),
        (Join-Path $LlamaCpp 'build-vulkan\bin'),
        (Join-Path $LlamaCpp 'build\bin\Release'),
        (Join-Path $LlamaCpp 'build\bin')
    )
    foreach ($candidate in $candidates) {
        if ((Test-Path (Join-Path $candidate 'llama.dll')) -and (Test-Path (Join-Path $candidate 'libllama.dll.a'))) {
            $BuildDir = $candidate
            break
        }
    }
    if (-not $BuildDir) {
        if ($UsingSubmodule) {
            Fail "No Windows shared build found under $LlamaCpp. From the repo root, run: tools\build-windows.ps1"
        }
        Fail "No folder with llama.dll and libllama.dll.a found under $LlamaCpp; pass the DLL folder as the second argument."
    }
}
if (Test-Path $BuildDir -PathType Container) {
    $BuildDir = (Resolve-Path $BuildDir).Path
}
if (-not (Test-Path (Join-Path $BuildDir 'libllama.dll.a'))) {
    Fail "libllama.dll.a not found in $BuildDir; generate the import libraries with tools\build-windows.ps1."
}

$Exe = Join-Path $PSScriptRoot 'hello_llama.exe'
$libArgs = @('-l', 'llama', '-l', 'ggml', '-l', 'ggml-base', '-l', 'ggml-cpu')
if (Test-Path (Join-Path $BuildDir 'libggml-cuda.dll.a')) { $libArgs += @('-l', 'ggml-cuda') }
if (Test-Path (Join-Path $BuildDir 'libggml-vulkan.dll.a')) { $libArgs += @('-l', 'ggml-vulkan') }

$fbArgs = @('-i', $IncDir, (Join-Path $PSScriptRoot 'hello_llama.bas'), '-p', $BuildDir) + $libArgs + @('-x', $Exe)
Write-Host ("fbc " + ($fbArgs -join ' '))
& fbc @fbArgs
if ($LASTEXITCODE -ne 0) { Fail "fbc failed with exit code $LASTEXITCODE." }
if (-not (Test-Path $Exe)) { Fail "fbc reported success but did not create $Exe" }
Write-Host "Built: $Exe"
